    15→
    16→    public ShardBlobNetworkWrapper AllocateWrapper(params ReadOnlySpan<byte[]> blobs)
    17→    {
    18→        ShardBlobNetworkWrapper result = new(blobs.ToArray(), new byte[blobs.Length][], new byte[blobs.Length * Ckzg.CellsPerExtBlob][], ProofVersion.V1);
    19→
    20→        for (int i = 0; i < blobs.Length; i++)
    21→        {
    22→            result.Commitments[i] = new byte[Ckzg.BytesPerCommitment];
